'use strict';
// V61 : conseil d'administration, jalons et evaluation des objectifs; hors match et sans effets de bord.
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.CDBoardCalendar=api})(typeof globalThis==='object'?globalThis:null,function(){
const copy=x=>JSON.parse(JSON.stringify(x)),valid=n=>typeof n==='number'&&Number.isFinite(n),requireValid=(v,m)=>{if(!v)throw Error(m)};
const TYPES=['wins','points','rank','cash'];
function create(clubId,season=1){requireValid(typeof clubId==='string'&&clubId&&Number.isInteger(season)&&season>=1,'Club ou saison invalide');return {version:1,clubId,season,week:0,trust:60,objectives:[],meetings:[],history:[]};}
function audit(s){requireValid(s&&s.version===1&&typeof s.clubId==='string'&&Number.isInteger(s.season)&&s.season>=1&&Number.isInteger(s.week)&&s.week>=0&&valid(s.trust)&&s.trust>=0&&s.trust<=100&&Array.isArray(s.objectives)&&Array.isArray(s.meetings)&&Array.isArray(s.history),'Etat direction invalide');requireValid(new Set(s.objectives.map(o=>o.id)).size===s.objectives.length,'Objectif double');return true;}
function objective(state,{id,type,target,deadline,weight=1}){audit(state);requireValid(typeof id==='string'&&id&&!state.objectives.some(o=>o.id===id)&&TYPES.includes(type)&&valid(target)&&target>=0&&Number.isInteger(deadline)&&deadline>state.week&&valid(weight)&&weight>0&&weight<=3,'Objectif invalide');const s=copy(state);s.objectives.push({id,type,target,deadline,weight,status:'pending'});return s;}
function review(state,{week,metrics={}}){audit(state);requireValid(Number.isInteger(week)&&week>=state.week,'Semaine invalide');const s=copy(state),events=[];for(const o of s.objectives){if(o.status!=='pending'||week<o.deadline)continue;const value=metrics[o.type];const status=!valid(value)?'unverified':(o.type==='rank'?value<=o.target:value>=o.target)?'met':'missed';o.status=status;const delta=status==='unverified'?0:(status==='met'?Math.round(5*o.weight):-Math.round(8*o.weight));s.trust=Math.max(0,Math.min(100,s.trust+delta));events.push({id:o.id,status,delta,week});}s.week=week;s.meetings.push({week,events});s.history.push({week,trust:s.trust});return {state:s,events};}
function briefing(s,metrics={}){audit(s);return {trust:s.trust,upcoming:s.objectives.filter(o=>o.status==='pending').map(o=>({id:o.id,type:o.type,deadline:o.deadline,target:o.target,current:valid(metrics[o.type])?metrics[o.type]:null})).sort((a,b)=>a.deadline-b.deadline||a.id.localeCompare(b.id)),risks:s.objectives.filter(o=>o.status==='missed').map(o=>o.id)};}
function nextSeason(state){audit(state);const s=copy(state);s.season++;s.week=0;s.objectives=[];s.meetings=[];return s;}
return Object.freeze({create,audit,objective,review,briefing,nextSeason});});
